function effetsScene(effects){
  (effects || []).forEach(function(e){
    if(e.kind === 'succes'){
      const s = succesDuJeu().filter(function(x){ return x.id === e.id; })[0];
      try{ hudNotify('\u{1F3C6} Succ\xE8s : ' + (s ? s.nom : e.id), 'gain'); }catch(err){}
    }
    else if(e.kind === 'fin'){ const fa = e.action; setTimeout(function(){ montrerFin(fa); }, 350); }
    if(e.kind === 'navigate') passageDemande = { cible: e.target, regard: e.regard || null, transition: e.transition || '' };
    else if(e.kind === 'regarder') animerRegard(e.action, e.action.duree);
    else if(e.kind === 'secouer'){
      const c = e.action.force === 'fort' ? 'tr-secoue-fort' : 'tr-secoue';
      mount.classList.remove('tr-secoue', 'tr-secoue-fort'); void mount.offsetWidth; mount.classList.add(c);
      setTimeout(function(){ mount.classList.remove(c); }, 800);
    }
    else if(e.kind === 'vibrer'){ try{ if(navigator.vibrate) navigator.vibrate(e.action.ms || 200); }catch(err){} }
    else if(e.kind === 'image') montrerImage(e.action.image, e.action.texte);
    else if(e.kind === 'bulle') montrerBulle(e.action);
    else if(e.kind === 'carnet'){ try{ hudPlaySound('notify'); }catch(x){} annonce('Ajout\xE9 au carnet', trJeu(e.action.titre || 'Document'), '', '\u{1F4C4}'); }
    else if(e.kind === 'cinematique') jouerCine(e.action.cineId);
    else if(e.kind === 'boutique') ouvrirBoutique(e.action.boutiqueId);
    else if(e.kind === 'sursaut') imSursaut(e.action);
    else if(e.kind === 'quete') queteAction(e.action);
    else if(e.kind === 'combat') setTimeout(function(){ cmbCommence(e.action.groupeId); }, 0);
    else if(e.kind === 'lot26') lot26Effet(e.action);
    else if(e.kind === 'av') avEffet(e);
    else if(e.kind === 'm42') mEffet(e);
    else if(e.kind === 'e43') eEffet(e);
    else if(e.kind === 'x44') xEffet(e);
    else if(e.kind === 'z45') zEffet(e);
    else if(e.kind === 'soigner_heros') heroSoigne(e.action.vie, e.action.energie);
    else if(e.kind === 'gagner_xp') heroGagneXp(e.action.montant);
    else if(e.kind === 'jet') jetMontre(e);
    else if(e.kind === 'paye') setTimeout(marchePaliers, 0);
    else if(e.kind === 'fragment'){ try{ hudPlaySound('notify'); }catch(x){} annonce('Fragment trouv\xE9', trJeu(e.action.texte), '', '\u{1F9E9}'); vibre(40); }
  });
}
