  const el = mk('div', 'z45-lv'); el.setAttribute('data-z45-longuevue', V.cadre || 'longuevue');
  const w = mount.clientWidth, h = mount.clientHeight, r = Math.min(w, h) * (V.cadre === 'jumelles' ? 0.3 : 0.38);
  const trous = V.cadre === 'jumelles' ? '<circle cx="' + (w / 2 - r * 0.82) + '" cy="' + (h / 2) + '" r="' + r + '" fill="black"/><circle cx="' + (w / 2 + r * 0.82) + '" cy="' + (h / 2) + '" r="' + r + '" fill="black"/>' : '<circle cx="' + (w / 2) + '" cy="' + (h / 2) + '" r="' + r + '" fill="black"/>';
  el.innerHTML = '<svg width="' + w + '" height="' + h + '" viewBox="0 0 ' + w + ' ' + h + '"><defs><mask id="z45lv"><rect width="' + w + '" height="' + h + '" fill="white"/>' + trous + '</mask></defs><rect width="' + w + '" height="' + h + '" fill="#000" mask="url(#z45lv)"/></svg>';
  mount.appendChild(el);
