    '.x44-fx-teleport{border-radius:40% 40% 8px 8px;background:linear-gradient(0deg,var(--c),transparent);box-shadow:0 0 30px var(--c);animation:x44pulse 1.2s ease-in-out infinite}',
    '.x44-fx-courtcircuit{border-radius:50%;background:radial-gradient(circle,#fff 0,#9fe4ff 15%,transparent 45%);animation:x44etincelle .7s steps(3) infinite}',
    '.x44-fx-ecran{border:1.5px solid var(--c);background:rgba(4,20,30,.6);color:var(--c);font:700 13px "Courier New",monospace;display:flex;align-items:center;justify-content:center;text-align:center;padding:6px;box-sizing:border-box;animation:x44flicker 4s infinite;box-shadow:0 0 12px var(--c)}',
