/* --- tutoriel du jeu : des bulles au premier lancement --- */
function tutoLance(){
  const l = plusCfg().tutoriel || [];
  if(!l.length || vars.__tuto || playerScreen !== 'playing' || balActif || morEnCours) return;
  vars.__tuto = 1;
  let i = 0;
  const ui = mk('div', '');
  ui.style.cssText = 'position:absolute;inset:0;z-index:58;display:flex;align-items:flex-end;justify-content:center;padding:0 14px 90px;background:rgba(0,0,0,.25)';
  const b = PlayerUI.mk('div', { background: '#161A25', color: '#E9E6DD', borderRadius: '12px', padding: '14px', maxWidth: '420px', width: '100%', font: '15px/1.45 sans-serif' });
  ui.appendChild(b); frameEl.appendChild(ui);
  const dess = function(){
    const e = l[i];
    if(!e){ ui.remove(); return; }
    b.textContent = '';
    if(e.yaw != null) animerRegard({ yaw: e.yaw, pitch: e.pitch || 0 }, 0.8);
    if(e.image){ const im = document.createElement('img'); im.src = e.image; im.alt = ''; im.style.cssText = 'max-width:100%;max-height:160px;display:block;margin:0 auto 8px'; b.appendChild(im); }
    b.appendChild(mk('div', '', trJeu(e.texte || '')));
    const s = PlayerUI.button(i === l.length - 1 ? 'Compris' : 'Suivant', function(){ i++; dess(); }, true);
    const p = PlayerUI.button('Passer', function(){ ui.remove(); });
    b.appendChild(s); b.appendChild(p);
  };
  dess();
}

/* --- mini-jeux en temps r\xE9el --- */
const MJ_NOMS = { crochetage: 'Crochetage', peche: 'P\xEAche', tir: 'Tir', rythme: 'Rythme' };
const MJ = {
  crochetage: function(g, o){
    const tol = 0.28 - 0.05 * o.diff, total = 2 + o.diff;
    let cible = Math.random() * 6.28, ang = 0, prog = 0, faites = 0, tient = false, temps = 45 - 8 * o.diff;
    return {
      down: function(x, y){ tient = true; ang = Math.atan2(y - 170, x - 160); },
      move: function(x, y){ if(tient) ang = Math.atan2(y - 170, x - 160); },
      up: function(){ tient = false; },
      maj: function(dt){
        temps -= dt; if(temps <= 0) return o.fin(false);
        const e = Math.abs(Math.atan2(Math.sin(ang - cible), Math.cos(ang - cible)));
        if(tient && e < tol){ prog += dt / 0.9; if(navigator.vibrate) try{ navigator.vibrate(4); }catch(x){} } else prog = Math.max(0, prog - dt * 1.4);
        if(prog >= 1){ prog = 0; faites++; cible = Math.random() * 6.28; if(faites >= total) return o.fin(true); }
        o.info.textContent = 'Goupilles ' + faites + ' / ' + total + ' \xB7 ' + Math.ceil(temps) + ' s';
        g.fillStyle = '#10131b'; g.fillRect(0, 0, 320, 380);
        const chaud = Math.max(0, 1 - e / 1.6);
        g.lineWidth = 16; g.strokeStyle = 'rgb(' + Math.round(70 + 185 * chaud) + ',' + Math.round(90 + 60 * chaud) + ',' + Math.round(150 - 110 * chaud) + ')';
        g.beginPath(); g.arc(160, 170, 110, 0, 6.3); g.stroke();
        g.strokeStyle = '#e8a33d'; g.lineWidth = 8; g.beginPath(); g.arc(160, 170, 88, -1.57, -1.57 + 6.28 * prog); g.stroke();
        g.strokeStyle = '#fff'; g.lineWidth = 5; g.beginPath(); g.moveTo(160, 170); g.lineTo(160 + Math.cos(ang) * 120, 170 + Math.sin(ang) * 120); g.stroke();
      }
    };
  },
  peche: function(g, o){
    const hb = 110 - 18 * o.diff;
    let barre = 150, vb = 0, poisson = 150, but = 150, prog = 0.3, tient = false, attend = 0;
    return {
      down: function(){ tient = true; }, up: function(){ tient = false; }, move: function(){},
      maj: function(dt){
        attend -= dt; if(attend <= 0){ attend = 0.4 + Math.random() * (1.2 - 0.25 * o.diff); but = 15 + Math.random() * 330; }
        poisson += (but - poisson) * dt * (1.4 + o.diff * 0.8);
        vb += (tient ? -620 : 460) * dt; barre += vb * dt;
        if(barre < 0){ barre = 0; vb = 0; } if(barre > 370 - hb){ barre = 370 - hb; vb *= -0.3; }
        const dans = poisson > barre && poisson < barre + hb;
        prog += (dans ? 0.32 : -0.24) * dt;
        if(prog >= 1) return o.fin(true); if(prog <= 0) return o.fin(false);
        o.info.textContent = 'Garde le doigt appuy\xE9 pour monter';
        g.fillStyle = '#123044'; g.fillRect(0, 0, 320, 380);
        g.fillStyle = 'rgba(120,220,160,.55)'; g.fillRect(120, barre + 5, 70, hb);
        g.font = '30px sans-serif'; g.textAlign = 'center'; g.fillStyle = '#fff'; g.fillText('\u{1F41F}', 155, poisson + 16);
        g.fillStyle = '#233'; g.fillRect(240, 10, 26, 360); g.fillStyle = '#e8a33d'; g.fillRect(240, 10 + 360 * (1 - prog), 26, 360 * prog);
      }
    };
  },
  tir: function(g, o){
    const but = 7 + 3 * o.diff;
    let cibles = [], score = 0, temps = 15, attend = 0;
    return {
      down: function(x, y){
        for(let i = cibles.length - 1; i >= 0; i--){ const c = cibles[i]; if(Math.hypot(x - c.x, y - c.y) < c.r + 8){ cibles.splice(i, 1); score++; if(score >= but) return o.fin(true); return; } }
      },
      move: function(){}, up: function(){},
      maj: function(dt){
        temps -= dt; if(temps <= 0) return o.fin(false);
        attend -= dt; if(attend <= 0){ attend = 0.75 - 0.13 * o.diff; cibles.push({ x: 40 + Math.random() * 240, y: 40 + Math.random() * 300, r: 34 - 5 * o.diff, v: 1.5 }); }
        cibles = cibles.filter(function(c){ c.v -= dt; return c.v > 0; });
        o.info.textContent = 'Cibles ' + score + ' / ' + but + ' \xB7 ' + Math.ceil(temps) + ' s';
        g.fillStyle = '#10131b'; g.fillRect(0, 0, 320, 380);
        cibles.forEach(function(c){ [[1, '#e0574f'], [0.66, '#fff'], [0.33, '#e0574f']].forEach(function(a){ g.fillStyle = a[1]; g.beginPath(); g.arc(c.x, c.y, c.r * a[0], 0, 6.3); g.fill(); }); });
      }
    };
  },
  rythme: function(g, o){
    const n = 14 + 5 * o.diff, ecart = 0.72 - 0.13 * o.diff, v = 210 + 40 * o.diff, notes = [];
    for(let i = 0; i < n; i++) notes.push({ l: Math.floor(Math.random() * 3), t: 1.4 + i * ecart, ok: 0 });
    let t = 0, reussies = 0;
    return {
      down: function(x){
        const l = Math.max(0, Math.min(2, Math.floor(x / 107)));
        let m = null, e = 0.2;
        notes.forEach(function(k){ if(!k.ok && k.l === l && Math.abs(k.t - t) < e){ e = Math.abs(k.t - t); m = k; } });
        if(m){ m.ok = 1; reussies++; }
      },
      move: function(){}, up: function(){},
      maj: function(dt){
        t += dt;
        if(t > notes[n - 1].t + 0.6) return o.fin(reussies / n >= 0.7);
        o.info.textContent = 'Notes r\xE9ussies ' + reussies + ' \xB7 il en faut ' + Math.ceil(n * 0.7);
        g.fillStyle = '#10131b'; g.fillRect(0, 0, 320, 380);
        g.fillStyle = 'rgba(255,255,255,.14)'; g.fillRect(0, 320, 320, 30);
        g.fillStyle = '#e8a33d';
        notes.forEach(function(k){ if(k.ok) return; const y = 335 - (k.t - t) * v; if(y > -20 && y < 400){ g.beginPath(); g.arc(53 + k.l * 107, y, 20, 0, 6.3); g.fill(); } });
      }
    };
  }
};
function mjOuvre(a){
  const fab = MJ[a.genre] || MJ.crochetage;
  const ov = PlayerUI.overlay(frameEl, 'data-minijeu'), box = PlayerUI.box(ov, trJeu(a.titre || MJ_NOMS[a.genre] || 'Mini-jeu'));
  ov.style.zIndex = '75';
  const info = PlayerUI.mk('div', { minHeight: '1.5em', marginBottom: '6px' }); box.appendChild(info);
  const cv = document.createElement('canvas'); cv.width = 320; cv.height = 380;
  cv.style.cssText = 'display:block;width:100%;max-width:320px;margin:auto;border-radius:10px;touch-action:none';
  box.appendChild(cv);
  let fini = false, raf = 0;
  const fin = function(ok){
    if(fini) return; fini = true; cancelAnimationFrame(raf); ov.remove();
    const l = ok ? a.gagne : a.perd;
    showModal(ok ? 'R\xE9ussi !' : 'Rat\xE9\u2026');
    if(l && l.length) actionsJoue(l);
  };
  const jeu = fab(cv.getContext('2d'), { diff: Math.max(1, Math.min(3, parseInt(a.difficulte, 10) || 2)), info: info, fin: fin });
  const pos = function(e){ const r = cv.getBoundingClientRect(); return [(e.clientX - r.left) * 320 / r.width, (e.clientY - r.top) * 380 / r.height]; };
  cv.addEventListener('pointerdown', function(e){ e.preventDefault(); try{ cv.setPointerCapture(e.pointerId); }catch(x){} const p = pos(e); jeu.down(p[0], p[1]); });
  cv.addEventListener('pointermove', function(e){ const p = pos(e); jeu.move(p[0], p[1]); });
  cv.addEventListener('pointerup', function(){ jeu.up(); });
  cv.addEventListener('pointercancel', function(){ jeu.up(); });
  box.appendChild(PlayerUI.button('Abandonner', function(){ fin(false); }));
  let t0 = performance.now();
  const boucle = function(t){
    if(fini) return;
    const dt = Math.min(0.05, (t - t0) / 1000); t0 = t;
    jeu.maj(dt);
    if(!fini) raf = requestAnimationFrame(boucle);
  };
  raf = requestAnimationFrame(boucle);
}

/* --- ce que d\xE9clenchent les actions du lot --- */
