/* --- cam\xE9ras de surveillance --- */
function camOuvrir(ids, titre){
  const liste = (ids || []).map(function(id){ return GAME.scenes.filter(function(s){ return s.id === id; })[0]; }).filter(Boolean).slice(0, 4);
  if(!liste.length) return;
  const ov = PlayerUI.overlay(frameEl, 'data-cameras'); ov.style.zIndex = '74';
  const box = PlayerUI.box(ov, trJeu(titre || 'Cam\xE9ras'));
  const g = PlayerUI.mk('div', { display: 'grid', gridTemplateColumns: liste.length > 1 ? '1fr 1fr' : '1fr', gap: '6px' });
  box.appendChild(g);
  const flux = liste.map(function(sc){
    const cv = document.createElement('canvas'); cv.width = 320; cv.height = 200;
    cv.style.cssText = 'width:100%;display:block;background:#000;border-radius:4px'; g.appendChild(cv);
    const o = { sc: sc, cv: cv, im: null };
    morCharge(sc).then(function(t){ if(t) o.im = t.image; });
    return o;
  });
  let fin = false;
  box.appendChild(PlayerUI.button('Quitter', function(){ fin = true; ov.remove(); }, true));
  const dess = function(){
    if(fin || !ov.parentNode) return;
    flux.forEach(function(o){
      const c = o.cv.getContext('2d'); c.fillStyle = '#000'; c.fillRect(0, 0, 320, 200);
      if(o.im && o.im.width){
        const w = o.im.width, h = o.im.height, reg = o.sc.regard ? o.sc.regard.yaw : 0;
        const dir = yawPitchToDir(reg, 0), u = ((Math.atan2(dir.z, dir.x) / (2 * Math.PI)) % 1 + 1) % 1;
        const sw = w * 0.26, sh = sw * 200 / 320, sx = u * w - sw / 2, sy = h / 2 - sh / 2;
        c.filter = 'grayscale(1) contrast(1.2) brightness(.9)';
        c.drawImage(o.im, sx, sy, sw, sh, 0, 0, 320, 200);
        if(sx < 0) c.drawImage(o.im, sx + w, sy, sw, sh, 0, 0, 320, 200);
        c.filter = 'none';
      }
      for(let i = 0; i < 260; i++){ c.fillStyle = 'rgba(255,255,255,' + (Math.random() * 0.16).toFixed(2) + ')'; c.fillRect(Math.random() * 320, Math.random() * 200, 2, 2); }
      c.fillStyle = 'rgba(0,0,0,.16)'; for(let y = (Date.now() / 40) % 4; y < 200; y += 4) c.fillRect(0, y, 320, 1);
      const present = tqActive() && vars.__tq_scene === o.sc.id;
      c.font = 'bold 13px monospace'; c.fillStyle = present ? '#ff4a4a' : '#7dff9c';
      c.fillText((present ? '\u25CF MOUVEMENT  ' : 'REC  ') + (o.sc.name || ''), 8, 18);
      if(present){
        const fc = tqCfg().image ? null : '\u{1F441}';
        c.font = '70px sans-serif'; if(fc) c.fillText(fc, 120, 150);
      }
    });
    setTimeout(function(){ requestAnimationFrame(dess); }, 90);
  };
  dess();
}

/* --- passants et foule --- */
let pasObjets = [], pasJeton = 0;
function pasRetire(){ pasJeton++; pasObjets.forEach(function(o){ o.el.remove(); }); pasObjets = []; }
function pasMasque(o, d, py, ya){
  const W = 20, H = 30, pxr = (mount.clientHeight || 1) / 2 / Math.tan(camera.fov * Math.PI / 360);
  const cv = document.createElement('canvas'); cv.width = W; cv.height = H;
  const c = cv.getContext('2d'), img = c.createImageData(W, H), dist = navDistance(py || 0);
  let cache = 0;
  for(let j = 0; j < H; j++) for(let i = 0; i < W; i++){
    const y2 = ya - ((i + 0.5) / W - 0.5) * o.el.offsetWidth / pxr, p2 = (py || 0) + (1 - (j + 0.5) / H) * o.el.offsetHeight / pxr;
    const v = yawPitchToDir(y2, p2), u = ((Math.atan2(v.z, v.x) / (2 * Math.PI)) % 1 + 1) % 1;
    const ix = (Math.max(0, Math.min(127, Math.floor((0.5 - p2 / Math.PI) * 128))) * 256 + Math.floor(u * 256)) * 4;
    const proche = d[ix + 3] > 128 && (1.5 + 48.5 * (d[ix] / 255) * (d[ix] / 255)) < dist;
    if(proche) cache++;
    img.data[(j * W + i) * 4 + 3] = proche ? 0 : 255;
  }
  if(!cache){ o.el.style.webkitMaskImage = ''; o.el.style.maskImage = ''; return; }
  c.putImageData(img, 0, 0);
  const u = 'url("' + cv.toDataURL() + '")';
  o.el.style.webkitMaskImage = u; o.el.style.webkitMaskSize = '100% 100%'; o.el.style.maskImage = u; o.el.style.maskSize = '100% 100%';
}
function pasPose(){
  pasRetire();
  const l = (imSc().passants || []).filter(function(p){ return p.image && (p.trajet || []).length >= 2; });
  if(!l.length) return;
  const jeton = pasJeton, t0 = performance.now();
  l.forEach(function(p, n){
    const el = document.createElement('img'); el.src = p.image; el.alt = ''; el.draggable = false;
    el.style.cssText = 'position:absolute;left:0;top:0;pointer-events:none;z-index:2;will-change:transform;transform-origin:50% 100%';
    mount.appendChild(el);
    const seg = [0]; let tot = 0;
    for(let i = 1; i < p.trajet.length; i++){ const a = p.trajet[i - 1], b = p.trajet[i]; tot += Math.hypot(Math.atan2(Math.sin(b.yaw - a.yaw), Math.cos(b.yaw - a.yaw)), b.pitch - a.pitch); seg.push(tot); }
    pasObjets.push({ el: el, p: p, seg: seg, tot: tot || 1, dec: n * 0.37, mask: 0 });
  });
  setTimeout(function(){
    animsCamera.push(function(t){
      if(jeton !== pasJeton) return true;
      if(playerScreen !== 'playing') return false;
      const h = mount.clientHeight || 1, pxr = h / 2 / Math.tan(camera.fov * Math.PI / 360);
      pasObjets.forEach(function(o){
        const D = Math.max(2, parseFloat(o.p.duree) || 14), P = Math.max(0, parseFloat(o.p.pause) || 2);
        const ph = (((t - t0) / 1000 / (D + P)) + o.dec) % 1, k = Math.min(1, ph * (D + P) / D), s = k * o.tot;
        let i = 1; while(i < o.seg.length - 1 && o.seg[i] < s) i++;
        const a = o.p.trajet[i - 1], b = o.p.trajet[i], f = (s - o.seg[i - 1]) / Math.max(0.0001, o.seg[i] - o.seg[i - 1]);
        const dy = Math.atan2(Math.sin(b.yaw - a.yaw), Math.cos(b.yaw - a.yaw));
        const ya = a.yaw + dy * f, py = a.pitch + (b.pitch - a.pitch) * f;
        const v = yawPitchToDir(ya, py).multiplyScalar(100).project(camera);
        if(v.z > 1 || k >= 1 || Math.abs(v.x) > 1.4){ o.el.style.visibility = 'hidden'; return; }
        const w = mount.clientWidth || 1, larg = Math.max(18, pxr * Math.tan((parseFloat(o.p.largeur) || 8) * Math.PI / 360) * 2 * navEchelle(py));
        const x = (v.x * 0.5 + 0.5) * w, y = (-v.y * 0.5 + 0.5) * h;
        o.el.style.visibility = 'visible'; o.el.style.width = larg + 'px';
        const pas = Math.abs(Math.sin(t / 170)) * larg * 0.03;
        o.el.style.transform = 'translate(' + (x - larg / 2).toFixed(1) + 'px,' + (y - (o.el.offsetHeight || larg * 2) - pas).toFixed(1) + 'px) scaleX(' + (dy < 0 ? -1 : 1) + ')';
        if(t - o.mask > 300){ o.mask = t; const d = prfDonnees(current); if(d) pasMasque(o, d, py, ya); }
      });
      return false;
    });
  }, 0);
}

