/* Actions jouees a l'arrivee dans une scene. La profondeur est bornee pour qu'une
   scene qui renvoie vers une autre ne parte pas en boucle. */
let enterDepth = 0;
function runSceneEnter(scene){
  if(!scene || !scene.onEnter || !scene.onEnter.length) return;
  if(!saveEnabled || playerScreen === 'home') return;
  if(enterDepth > 4) return;
  if(scene.onEnterUneFois){
    if(vars['__entre:' + scene.id]) return;
    vars['__entre:' + scene.id] = true;
  }
  enterDepth++;
  try{
    const eff = runActions(scene.onEnter);
    const d = pickDialogue(eff);
    if(d && playerScreen === 'playing') openDialogue(d);
    const nav = pickNavigate(eff, null);
    if(nav && nav !== scene.id) loadScene(nav);
  } finally { enterDepth--; }
}

